(()=>{'use strict';const A=RepoAccount,$=s=>document.querySelector(s);let identity=null,busy=false,epoch=0,deleted=false;
const KEY='reposhelf.analytics.consent.v2',stored=()=>{try{return localStorage.getItem(KEY)==='yes'}catch{return false}},blockedBySignal=()=>navigator.globalPrivacyControl||navigator.doNotTrack==='1';
function showMethods(){const box=$('#signin-methods');box.hidden=!identity;if(!identity)return;const p=A.user.providers||[],hasGh=p.includes('github'),hasG=p.includes('google'),can=A.googleEnabled;$('#signin-methods-text').textContent=hasGh&&hasG?'Connected: GitHub and Google. Whichever you sign in with, you will see the same collection, submissions and history.':hasGh?'You are signed in with GitHub.'+(can?' Connect Google as well so you can sign in either way and still see the same collection, submissions and history.':' GitHub unlocks forks, repository submissions and reports.'):'You are signed in with Google. Connect GitHub to track forks, submit repositories and report listings. It is added to this same account, so your likes and collection stay.';$('#connect-github').hidden=hasGh;$('#connect-google').hidden=hasG||!can;const q=new URLSearchParams(location.search);$('#link-status').textContent=q.get('link')==='failed'?'That sign-in could not be connected. If you already use it as a separate RepoShelf account, it cannot be linked yet. Otherwise try again, and contact the administrator if it keeps failing.':q.get('linked')==='github'?'GitHub is connected.':q.get('linked')==='google'?'Google is connected.':''}
const MERGE_REASONS={same_account:'That is the account you are already signed in with.',account_missing:'One of the accounts no longer exists.',same_provider:'Both accounts use the same sign-in method, so they cannot be merged.',source_is_admin:'The other account is an administrator account. Make this account an administrator first, then try again.',promotions_active:'A promotion is reserved or running. Resolve it first, then try again.',busy:'A background check is running on one of the accounts. Try again in a few minutes.'},PROVIDER_NAMES={github:'GitHub',google:'Google'};
function showMerge(){const box=$('#merge-accounts');const p=A.user?.providers||[],options=['github','google'].filter(x=>!p.includes(x)&&(x!=='google'||A.googleEnabled));const q=new URLSearchParams(location.search),state=q.get('merge');box.hidden=!identity||(!options.length&&!state);if(box.hidden)return;
 const have=p.map(x=>PROVIDER_NAMES[x]).filter(Boolean).join(' and ')||'this sign-in method';$('#merge-intro').textContent=options.length?`Signed in with ${have} one day and another method on another, and ended up with two RepoShelf accounts? You can merge them. The account you are signed in to now keeps everything, and the other is closed. You will sign in to the other one once to prove it is yours, and nothing moves until you confirm.`:'';
 $('#merge-starts').replaceChildren(...options.map(x=>{const a=document.createElement('a');a.className='button outline';a.href='/api/auth?action=merge-start&provider='+x;a.textContent=`I also have a separate ${PROVIDER_NAMES[x]} account`;return a}));
 const status=$('#merge-status');status.textContent={failed:'The other account could not be confirmed. Please try again.',already:'That sign-in method is already connected to this account.',same:'Those sign-in methods already belong to one account, so there is nothing to merge.',blocked:MERGE_REASONS[q.get('reason')]||'These accounts cannot be merged.'}[state]||'';
 if(state==='ready')void loadMergePreview()}
async function loadMergePreview(){try{const data=await A.request('/api/auth?action=merge-preview'),c=data.counts||{},bits=[['liked projects',c.likes],['recently viewed items',c.history],['verified forks',c.forks],['repository submissions',c.submissions],['promotions',c.promotions]].filter(([,n])=>n>0).map(([label,n])=>`${n} ${label}`);
  $('#merge-summary').textContent=`We found your separate ${PROVIDER_NAMES[data.provider]||'other'} account. Merging moves ${bits.length?bits.join(', '):'nothing, because it has no saved data'} into this account (${data.keeps}), then closes the other account. This cannot be undone. Afterwards you will reconnect ${PROVIDER_NAMES[data.provider]||'that sign-in method'} to this account so you can use either to sign in.`;$('#merge-panel').hidden=false;$('#merge-starts').hidden=true}catch(e){$('#merge-status').textContent=e.message}}
$('#merge-confirmation').oninput=()=>$('#merge-run').disabled=$('#merge-confirmation').value!=='MERGE'||busy;
$('#merge-cancel').onclick=async()=>{try{await A.request('/api/auth?action=merge-cancel',{method:'POST',body:'{}'})}catch{}history.replaceState(null,'','/account.html');$('#merge-panel').hidden=true;$('#merge-starts').hidden=false;$('#merge-status').textContent='Merge cancelled. Nothing was changed.'};
$('#merge-form').onsubmit=async e=>{e.preventDefault();if(busy||$('#merge-confirmation').value!=='MERGE')return;busy=true;$('#merge-run').disabled=true;$('#merge-status').textContent='Merging…';try{const data=await A.request('/api/auth?action=merge-confirm',{method:'POST',body:JSON.stringify({confirm:'MERGE'})});$('#merge-panel').hidden=true;
  if(data.closed){$('#merge-status').textContent=`Merged. Now reconnecting ${PROVIDER_NAMES[data.reconnect]||'your other sign-in method'}…`;setTimeout(()=>{location.href='/api/auth?action=link-'+encodeURIComponent(data.reconnect)+'&return=%2Faccount.html'},1500)}else $('#merge-status').textContent='Your data was moved, but the other account could not be closed automatically. Contact the administrator before reconnecting that sign-in method.'}catch(err){$('#merge-status').textContent=err.message;$('#merge-run').disabled=false}finally{busy=false}};
function showAnalytics(){const box=$('#analytics-consent');$('#analytics-settings').hidden=!identity;box.checked=stored();$('#analytics-status').textContent=blockedBySignal()?'Your browser’s Do Not Track or Global Privacy Control signal is on, so analytics stays off here whatever this setting says.':''}
$('#analytics-consent').onchange=e=>{const on=e.target.checked;try{localStorage.setItem(KEY,on?'yes':'no');if(!on){localStorage.removeItem('reposhelf.analytics.visitor');sessionStorage.removeItem('reposhelf.analytics.session')}window.dispatchEvent(new Event('reposhelf-privacy'));$('#analytics-status').textContent=on?'Analytics is on for this browser.':'Analytics is off for this browser.'}catch{e.target.checked=stored();$('#analytics-status').textContent='Your browser could not save this setting. Analytics stays as it was.'}};
async function refresh(){const turn=++epoch;identity=A.user?.id;showAnalytics();showMethods();showMerge();$('#account-data-tools').hidden=true;$('#account-data-signin').hidden=Boolean(identity);if(!identity){if(deleted){$('#account-data-status').textContent='Your RepoShelf account has been deleted. You can continue browsing.';$('#account-data-signin').hidden=true;return}$('#account-data-status').textContent='Sign in with GitHub to manage your account data.';return}try{const data=await A.request('/api/auth?action=data-state');if(turn!==epoch||identity!==A.user?.id)return;$('#account-data-tools').hidden=!data.ready;$('#account-data-status').textContent=data.ready?'Signed in as @'+A.user.name:'Account data controls are awaiting a database update. Your existing collection remains available.'}catch(e){if(turn===epoch)$('#account-data-status').textContent=e.message}}
$('#export-account').onclick=async()=>{if(busy||!identity)return;busy=true;const owner=identity;$('#export-account').disabled=true;$('#export-status').textContent='Preparing your private export…';try{const data=await A.request('/api/auth?action=export-account');if(A.user?.id!==owner)throw Error('Your account changed. Please try again.');const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='reposhelf-account-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#export-status').textContent='Your export is ready. Check your downloads.'}catch(e){$('#export-status').textContent=e.message}finally{busy=false;$('#export-account').disabled=false}};
$('#delete-confirmation').oninput=()=>$('#delete-account').disabled=$('#delete-confirmation').value!=='DELETE'||busy;
$('#delete-account-form').onsubmit=async e=>{e.preventDefault();if(busy||$('#delete-confirmation').value!=='DELETE')return;busy=true;$('#delete-account').disabled=true;$('#delete-status').textContent='Deleting your account…';try{await A.request('/api/auth?action=delete-account',{method:'DELETE',body:JSON.stringify({confirm:'DELETE'})});deleted=true;for(const key of ['reposhelf.collection.v1','reposhelf.demos.v3','reposhelf.likes.guest.v1','reposhelf.analytics.visitor'])try{localStorage.removeItem(key)}catch{}try{sessionStorage.removeItem('reposhelf.analytics.session');sessionStorage.removeItem('reposhelf.analytics.signin')}catch{}$('#account-data-tools').hidden=true;$('#account-data-status').textContent='Your RepoShelf account has been deleted. You can continue browsing.';$('#account-data-signin').hidden=true;await A.refresh()}catch(err){$('#delete-status').textContent=err.message}finally{busy=false;$('#delete-account').disabled=$('#delete-confirmation').value!=='DELETE'}};
window.addEventListener('reposhelf-account',()=>{if(identity!==A.user?.id)void refresh()});if(A.ready)void refresh();
})();
